<script setup lang="ts">import {ref,onMounted} from 'vue';import {api} from '../api';import DataPanel from './DataPanel.vue';const props=defineProps<{organizationId:number}>(),data=ref<any>(),error=ref(''),busy=ref(false);async function load(){try{data.value=await api('/api/organizations/'+props.organizationId+'/billing')}catch(e:any){error.value=e.message}}async function change(action:string,plan_id?:number){busy.value=true;try{await api('/api/organizations/'+props.organizationId+'/billing','POST',{action,plan_id,idempotency_key:crypto.randomUUID()});await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}onMounted(load);</script><template><section><h2>Plan and billing</h2><p v-if="error" role="alert" class="alert error">{{error}}</p><p class="notice">{{data?.notice}} Nothing on this page charges a card. A success page never turns a plan on by itself.</p><DataPanel :data="data?.subscription||{status:'unconfigured'}"/><div class="module-grid"><article v-for="p in data?.plans" class="card"><h3>{{p.name}}</h3><p>{{p.pricing_status}}</p><DataPanel :data="p.commercial||{price:'Not approved'}"/><p>{{p.file_limit}} files · {{p.member_limit}} members</p><button :disabled="busy||!p.commercial||data.provider!=='fake'" @click="change('upgrade',p.id)">Request upgrade</button><button :disabled="busy||!p.commercial||data.provider!=='fake'" @click="change('downgrade',p.id)">Request downgrade</button></article></div><button :disabled="busy||data?.provider!=='fake'" @click="change('cancel')">Request cancellation</button><h3>Usage</h3><DataPanel :data="data?.usage"/><h3>Billing history</h3><DataPanel :data="data?.history"/><DataPanel :data="data?.policies"/></section></template>